"""Transport fixtures only; generated bytes are not Unreal assets."""
import hashlib
import json
from pathlib import Path
import stat
import tempfile
import unittest
from unittest.mock import patch
import zipfile
import asset_delivery as delivery

ROOT = Path(__file__).resolve().parent


class Cases(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(dir=ROOT, prefix='CPU_ONLY_TRANSPORT_')
        self.root = Path(self.temp.name).resolve()
        self.assertTrue(self.root.is_relative_to(ROOT.resolve()))
        # The cleanup target is explicitly checked within this owned F directory.
        self.addCleanup(self.temp.cleanup)
        self.constants = patch.multiple(delivery, EXPECTED_ASSETS=2, EXPECTED_ASSET_BYTES=8)
        self.constants.start()
        self.addCleanup(self.constants.stop)

    def fixture(self):
        sources = self.root / 'Source'
        sources.mkdir()
        paths = [
            ('Content/LivingTown_UEPilot/A.uasset', b'CPU1', 'engine_asset'),
            ('Content/LivingTown_UEPilot/B.uasset', b'CPU2', 'engine_asset'),
            ('Content/LivingTown_UEPilot/Presentation/CPU_ONLY.umap', b'NOT A MAP', 'map'),
            ('Content/LivingTown/CafeProjectionBinding.json', b'{"asset":"/Game/A.A"}', 'binding'),
            ('Content/LivingTown/CafeJourneyRoute.json', b'{"route":[]}', 'route')
        ]
        rows = []
        for i, (name, data, role) in enumerate(paths):
            path = sources / str(i)
            path.write_bytes(data)
            rows.append({'path': name, 'source': delivery.file_record(path), 'role': role})
        plan = {'metadata': {'schema': delivery.SCHEMA, 'asset_count': 2, 'asset_bytes': 8,
                             'map': '/Game/LivingTown_UEPilot/Presentation/CPU_ONLY'},
                'entries': rows, 'map_input_receipts': []}
        path = self.root / 'PLAN.json'
        delivery.write(path, plan)
        return path, rows

    def archive(self):
        plan, rows = self.fixture()
        output = self.root / 'CPU_ONLY.zip'
        delivery.pack(plan, output)
        return output, rows

    def mutate(self, original, transform):
        target = self.root / 'BAD_CPU_ONLY.zip'
        with zipfile.ZipFile(original) as source, zipfile.ZipFile(target, 'x') as output:
            for info in source.infolist():
                changed = transform(info.filename, source.read(info))
                if changed is not None:
                    output.writestr(info, changed)
        return target

    def test_roundtrip_fresh_content_and_existing_destination_refusal(self):
        archive, rows = self.archive()
        destination = self.root / 'Fresh'
        result = delivery.install(archive, destination)
        self.assertEqual(result['status'], 'PASS_CONTENT_ONLY_FRESH_DIRECTORY')
        self.assertFalse((destination / 'INSTALL_INCOMPLETE.json').exists())
        for row in rows:
            self.assertEqual((destination / row['path']).read_bytes(), Path(row['source']['path']).read_bytes())
        sentinel = destination / 'KEEP_LOCAL.txt'
        sentinel.write_text('preserve')
        with self.assertRaises(ValueError):
            delivery.install(archive, destination)
        self.assertEqual(sentinel.read_text(), 'preserve')

    def test_bad_payload_byte_rejected_before_destination_created(self):
        original, _ = self.archive()
        bad = self.mutate(original, lambda name, data: b'BAD1' if name.endswith('A.uasset') else data)
        destination = self.root / 'MustNotExist'
        with self.assertRaises(ValueError):
            delivery.install(bad, destination)
        self.assertFalse(destination.exists())

    def test_map_capture_cannot_advertise_another_native_build(self):
        native = {'status': 'PASS_NATIVE_EDITOR_BUILD', 'source': {'sha256': 'source-A'}}
        native_path = self.root / 'NativeBuild.json'
        native_path.write_text(json.dumps(native))
        native_record = delivery.file_record(native_path)
        bootstrap_path = self.root / 'Bootstrap.json'
        bootstrap = {'status': 'PASS_ACTUAL_NATIVE_MCP_DISCOVERY_IMPORT_PENDING',
                     'native_build': {'receipt': {'sha256': native_record['sha256']},
                                      'source_sha256': 'source-A'}}
        bootstrap_path.write_text(json.dumps(bootstrap))
        owner = {'bootstrap_report': delivery.file_record(bootstrap_path)}
        self.assertEqual(delivery.matching_map_build(owner, native_record, native),
                         owner['bootstrap_report'])
        for key in ('receipt', 'source_sha256'):
            changed = json.loads(json.dumps(bootstrap))
            if key == 'receipt':
                changed['native_build'][key]['sha256'] = 'another-build'
            else:
                changed['native_build'][key] = 'another-source'
            bootstrap_path.write_text(json.dumps(changed))
            owner = {'bootstrap_report': delivery.file_record(bootstrap_path)}
            with self.subTest(key=key), self.assertRaisesRegex(ValueError, 'advertised native build differ'):
                delivery.matching_map_build(owner, native_record, native)

    def test_missing_asset_is_not_a_closed_archive(self):
        original, _ = self.archive()
        bad = self.mutate(original, lambda name, data: None if name.endswith('B.uasset') else data)
        with self.assertRaises(ValueError):
            delivery.verify_archive(bad)

    def test_duplicate_zip_member_refused(self):
        original, _ = self.archive()
        with zipfile.ZipFile(original, 'a') as archive:
            with self.assertWarns(UserWarning):
                archive.writestr('Content/LivingTown_UEPilot/A.uasset', b'CPU1')
        with self.assertRaises(ValueError):
            delivery.verify_archive(original)

    def test_traversal_case_device_and_prefix_collisions(self):
        for name in ('../escape', '/absolute', 'C:/host', 'a\\b', 'a/../b', 'a/NUL.json', 'a/trim. '):
            with self.subTest(name=name), self.assertRaises(ValueError):
                delivery.safe_relative(name)
        for paths in (['A/B', 'a/b'], ['A', 'A/B'], ['e\u0301.txt', '\u00e9.txt']):
            with self.assertRaises(ValueError):
                delivery.unique_paths(paths)

    def test_zip_symlink_and_extra_file_refused(self):
        original, _ = self.archive()
        info = zipfile.ZipInfo('Provenance/LINK.json')
        info.create_system = 3
        info.external_attr = (stat.S_IFLNK | 0o777) << 16
        with zipfile.ZipFile(original, 'a') as archive:
            archive.writestr(info, '../../outside')
        with self.assertRaises(ValueError):
            delivery.verify_archive(original)

    def test_changed_source_and_missing_source_refused(self):
        plan, rows = self.fixture()
        source = Path(rows[0]['source']['path'])
        source.write_bytes(b'BAD1')
        with self.assertRaises(ValueError):
            delivery.pack(plan, self.root / 'NoArchive.zip')
        self.assertFalse((self.root / 'NoArchive.zip').exists())
        source.unlink()
        with self.assertRaises(FileNotFoundError):
            delivery.pack(plan, self.root / 'NoArchive2.zip')

    def test_host_paths_refused_in_runtime_data(self):
        for value in ('F:\\Private\\asset.uasset', 'D:/Dev/asset', '\\\\host\\share\\asset'):
            with self.assertRaises(ValueError):
                delivery.portable_runtime_json({'nested': [value]})
        delivery.portable_runtime_json({'asset': '/Game/LivingTown_UEPilot/A.A'})


if __name__ == '__main__':
    suite = unittest.defaultTestLoader.loadTestsFromTestCase(Cases)
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    path = ROOT / 'CPU_TEST_REPORT.json'
    path.write_text(json.dumps({'status': 'PASS_CPU_TRANSPORT_FIXTURES_NOT_UNREAL' if result.wasSuccessful() else 'FAIL',
                               'tests_run': result.testsRun, 'failures': len(result.failures),
                               'errors': len(result.errors), 'skipped': len(result.skipped),
                               'engine_launched': False}, indent=2) + '\n', encoding='utf-8')
    raise SystemExit(not result.wasSuccessful())
